"""
    Gather statistics about the text, primarily the average word length
    Parameters
    ----------
    txt : str
    Returns
    -------
    word_length : float
        Average word length in the text
    """
def average_word_length(txt: Any) -> object {
    nw = len(txt.split());
    nc = len(txt);
    avgw = nc / (nw + 1);
    return avgw;
}

